mapper.select:
SELECT acl.user_id AS userId, acl.username AS name, acl.phone AS phone, COUNT(*) AS chatCount, MAX(acl.created_at) AS lastChatTime, IFNULL(SUM(acl.prompt_tokens + acl.completion_tokens), 0) AS totalTokens FROM ai_chat_log acl
acl.phone LIKE CONCAT('%', #{phone}, '%')
GROUP BY acl.user_id, acl.username, acl.phone ORDER BY lastChatTime DESC LIMIT #{limit} OFFSET #{offset}

SELECT id, user_id AS userId, username, phone, question, answer, from_knowledge AS fromKnowledge,
       model, prompt_tokens AS promptTokens, completion_tokens AS completionTokens, created_at AS createdAt
FROM ai_chat_log
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}
